/* MAFNR public site — no framework, dependencies or server required. */
(()=>{'use strict';
const D=window.MAFNR, page=document.body.dataset.page||'index', params=new URLSearchParams(location.search);
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={
 search:'<circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',x:'<path d="M18 6 6 18M6 6l12 12"/>',chevron:'<path d="m6 9 6 6 6-6"/>',right:'<path d="m5 12 14 0m-6-6 6 6-6 6"/>',check:'<path d="m4 12 5 5L20 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/>',sprout:'<path d="M12 22V12m0 0C5 12 4 8 4 3c6 0 8 3 8 9Zm0 2c0-8 3-10 9-10 0 7-2 10-9 10Z"/>',fish:'<path d="M6.5 12c3-6 8-8 14-6-1 3-1 9 0 12-6 2-11 0-14-6ZM6.5 12 2 7v10l4.5-5Z"/><circle cx="15" cy="11" r="1"/>',trees:'<path d="m7 3 5 7H9l5 6H2l5-6H4l3-7ZM7 16v6M18 4l4 6h-3l4 6H13l4-6h-3l4-6Zm0 12v6"/>',leaf:'<path d="M20 4c-11 0-16 3-16 11a5 5 0 0 0 5 5c8 0 11-5 11-16ZM4 20c3-5 7-8 12-11"/>',droplets:'<path d="M12 3C8 9 5 12 5 15a7 7 0 0 0 14 0c0-3-3-6-7-12Z"/><path d="M9 16a3 3 0 0 0 3 3"/>',waves:'<path d="M2 8c3-3 5-3 8 0s5 3 8 0 5-3 4 0M2 14c3-3 5-3 8 0s5 3 8 0 5-3 4 0M2 20c3-3 5-3 8 0s5 3 8 0 5-3 4 0"/>',tractor:'<path d="M10 11h9l-2-5h-6l-1 5ZM4 15V9h5v6M6 9V5H3M9 15h8M2 19h2m4 0h7"/><circle cx="6" cy="18" r="3"/><circle cx="18" cy="17" r="4"/>',heart:'<path d="M20 4c-2.5-2-6-1-8 2-2-3-5.5-4-8-2C-2 10 12 21 12 21S26 10 20 4Z"/>',anchor:'<circle cx="12" cy="5" r="2"/><path d="M12 7v14m-7-9h14M5 15a7 7 0 0 0 14 0M2 12h4m12 0h4"/>',ship:'<path d="M2 18l10 4 10-4-2-9H4L2 18ZM12 2v7M7 9V5h10v4"/>',clipboard:'<rect x="5" y="4" width="14" height="18" rx="2"/><rect x="9" y="2" width="6" height="4" rx="1"/><path d="M9 12h6M9 16h6"/>', 'file-text':'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h8"/>',map:'<path d="m3 5 6-2 6 3 6-2v15l-6 2-6-3-6 2V5ZM9 3v15m6-12v15"/>',mountain:'<path d="m2 20 7-13 4 6 3-4 6 11H2Zm5-8 3 3 3-2"/>',landmark:'<path d="m2 10 10-7 10 7H2ZM4 21h16M5 10v10m5-10v10m4-10v10m5-10v10"/>',users:'<circle cx="9" cy="7" r="4"/><path d="M2 21v-3a7 7 0 0 1 14 0v3M17 4a4 4 0 0 1 0 8m1 3a6 6 0 0 1 4 6"/>',network:'<rect x="9" y="2" width="6" height="6" rx="1"/><rect x="2" y="16" width="6" height="6" rx="1"/><rect x="16" y="16" width="6" height="6" rx="1"/><path d="M12 8v4M5 16v-4h14v4"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>','check-circle':'<circle cx="12" cy="12" r="10"/><path d="m7 12 3 3 7-7"/>','hand-coins':'<circle cx="18" cy="6" r="4"/><path d="M2 14h5l4 2h6a2 2 0 0 1-2 3h-7m-6 2h5l3 1 9-4a2 2 0 0 0-2-4l-5 2"/>',briefcase:'<rect x="2" y="7" width="20" height="15" rx="2"/><path d="M8 7V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v3M2 13h20"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 11h18"/>',mail:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m2 6 10 8 10-8"/>',phone:'<path d="M4 3h5l2 5-3 2c2 4 4 6 8 8l2-3 5 2v5C11 24 1 14 4 3Z"/>',clock:'<circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="2"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M3 18v3h18v-3"/>',printer:'<path d="M6 9V3h12v6M6 18H3V10h18v8h-3M6 15h12v7H6z"/>',trash:'<path d="M3 6h18M8 6V3h8v3M6 6l1 16h10l1-16M10 10v8m4-8v8"/>',edit:'<path d="m3 17 1 4 4-1L21 7l-4-4L4 16Z"/>',book:'<path d="M4 3h13a3 3 0 0 1 3 3v15H7a3 3 0 0 1-3-3V3Zm0 14a3 3 0 0 1 3-3h13"/>',alert:'<path d="m12 2 10 18H2L12 2Zm0 7v4m0 4h.01"/>',external:'<path d="M14 3h7v7m-9 3 9-10M21 14v7H3V3h7"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6m0-10v.01"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>',home:'<path d="m3 10 9-7 9 7v11H3V10Zm6 11v-8h6v8"/>',filter:'<path d="M3 4h18l-7 8v7l-4 2v-9L3 4Z"/>',lock:'<rect x="4" y="10" width="16" height="12" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 17v4h18v-4"/>'};
const icon=(name,cls='')=>`<svg class="${e(cls)}" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.info}</svg>`;
const go=(id)=>id.includes('.html')?id:id+'.html';
const link=(url,label,ic='right')=>`<a class="text-link" href="${e(url)}">${e(label)} ${icon(ic)}</a>`;
const card=(title,desc,url,ic='leaf',compact=false)=>`<article class="card card-fill ${compact?'compact-card':''}"><div class="iconbox">${icon(ic)}</div><h3><a href="${e(url)}">${e(title)}</a></h3><p>${e(desc)}</p>${link(url,'Explore this topic')}</article>`;
const crumbs=(title,group)=>{let parts=[['Home','index.html']];if(group&&!['Home','Services','News & resources'].includes(group))parts.push([group,go(group.toLowerCase().replaceAll(' ','-'))]);if(group==='Services')parts.push(['Services','services.html']);if(group==='News & resources')parts.push(['News & resources','news.html']);return `<nav class="crumbs" aria-label="Breadcrumb">${parts.map(x=>`<a href="${e(x[1])}">${e(x[0])}</a>${icon('right')}`).join('')}<span aria-current="page">${e(title)}</span></nav>`};
const banner=(title,desc,group,act='',label='')=>`<section class="page-banner"><div class="container">${crumbs(title,group)}<span class="eyebrow">${e(label||group||'The ministry')}</span><h1>${e(title)}</h1><p class="lead">${e(desc)}</p>${act?`<div class="banner-actions button-row">${act}</div>`:''}</div></section>`;
const related=(ids)=>ids?.length?`<section class="related-section"><div class="container"><div class="section-heading"><div><span class="kicker">Keep exploring</span><h2>Related information</h2></div></div><div class="related-list">${[...new Set(ids)].map(id=>{let t=D.pages[id]?.title||D.permits.find(p=>go(p.id+'-permit')===id)?.title||displayTitle(id);return `<a href="${e(id)}">${e(t)}${icon('right')}</a>`}).join('')}</div></div></section>`:'';
function displayTitle(url){let f=url.split('?')[0].replace('.html','');let names={'agricultural-permit':'Agricultural activity permit','commercial-fishing-licence':'Commercial fishing licence','recreational-fishing-licence':'Recreational fishing permit enquiry','aquaculture-permit':'Aquaculture development permit','forestry-permit':'Forestry activity permit','water-use-permit':'Water extraction or use permit','mining-permit':'Mineral exploration or extraction permit','land-access-permit':'Public land access or activity permit','report-catch':'Catch log tool','report-issue':'Report a concern','register-holding':'Register an agricultural holding','my-applications':'Saved draft applications'};return names[f]||f.split('-').map(s=>s[0].toUpperCase()+s.slice(1)).join(' ')}
function header(){let nav=D.nav.map(n=>`<div class="nav-group"><a class="nav-main" href="${n.url}">${e(n.label)}</a><button class="nav-chevron" type="button" aria-label="Show ${e(n.label)} links" aria-expanded="false">${icon('chevron')}</button><div class="nav-drop">${n.items.map(it=>`<a href="${it[1]}">${e(it[0])}</a>`).join('')}</div></div>`).join('');let mob=D.nav.map(n=>`<details><summary>${e(n.label)} ${icon('chevron')}</summary><a href="${n.url}"><strong>${e(n.label)} overview</strong></a>${n.items.filter(it=>it[1]!==n.url).map(it=>`<a href="${it[1]}">${e(it[0])}</a>`).join('')}</details>`).join('');return `<a class="skip-link" href="#main">Skip to main content</a><div class="govbar"><div class="container"><span class="govbar-left"><span class="govbar-dot"></span> SQUARE COUNTRY GOVERNMENT <span style="opacity:.5">/</span> OFFICIAL MINISTRY PORTAL DEMO</span><div class="govbar-links"><a href="accessibility.html">Accessibility</a><a href="contact.html">Contact</a><a href="sitemap.html">Site map</a></div></div></div><header class="site-header"><div class="container head-inner"><a href="index.html" class="brand" aria-label="Ministry homepage"><img src="images/mafnr-logo.png" onerror="this.onerror=null;this.src='assets/brand.svg'" alt="Ministry of Agriculture, Fisheries and Natural Resources"></a><nav aria-label="Main navigation" class="desktop-nav">${nav}</nav><div class="head-actions"><button class="search-icon-btn" data-open-search type="button" aria-label="Search website">${icon('search')}</button><a class="btn login-btn" href="login.html">Login</a><button type="button" class="mobile-menu-btn" aria-label="Open mobile menu" aria-controls="mobile-nav" aria-expanded="false">${icon('menu')}</button></div></div><nav id="mobile-nav" class="mobile-nav" aria-label="Mobile navigation"><form action="search.html" class="searchbar" role="search"><input name="q" type="search" placeholder="Search this website" aria-label="Search website"><button class="btn" type="submit">${icon('search')}</button></form>${mob}<a class="btn" href="login.html">Login</a></nav></header><div class="search-overlay" role="dialog" aria-modal="true" aria-label="Search the ministry website" aria-hidden="true"><div class="search-dialog"><div class="top"><div><span class="kicker" style="margin:0">Search the website</span><h2 style="margin:5px 0 0">What are you looking for?</h2></div><button class="close-btn" data-close-search aria-label="Close search">${icon('x')}</button></div><form class="searchbar" action="search.html" role="search"><input type="search" name="q" placeholder="Try: fishing licences, water, farming..." aria-label="Search all pages" required><button class="btn" type="submit">Search ${icon('right')}</button></form><p class="search-hints">Popular: <a href="licences.html">Licences</a> · <a href="biosecurity.html">Biosecurity</a> · <a href="fisheries-rules.html">Fishing rules</a> · <a href="consultations.html">Consultations</a></p></div></div><div id="toast" class="toast" role="status" aria-live="polite"></div>`}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-top"><div><a href="index.html"><img class="footer-logo" src="assets/brand.svg" alt="MAFNR — Square Country Government"></a><p class="brand-note">Supporting responsible agriculture, sustainable fisheries and stewardship of Square Country’s natural resources.</p><p class="brand-note" style="font-size:11px;opacity:.82">${e(D.disclaimer)}</p></div><div><h3>Our portfolios</h3><div class="footer-links"><a href="agriculture.html">Agriculture</a><a href="fisheries.html">Fisheries</a><a href="natural-resources.html">Natural resources</a><a href="biosecurity.html">Biosecurity</a><a href="biodiversity.html">Biodiversity</a><a href="grants.html">Grants and support</a></div></div><div><h3>Services & information</h3><div class="footer-links"><a href="services.html">All services</a><a href="licences.html">Licences and permits</a><a href="register-holding.html">Register a holding</a><a href="my-applications.html">Saved drafts</a><a href="downloads.html">Forms & downloads</a><a href="publications.html">Publications</a><a href="faq.html">Frequently asked questions</a></div></div><div><h3>Get involved</h3><div class="footer-links"><a href="news.html">News and updates</a><a href="notices.html">Public notices</a><a href="consultations.html">Consultations</a><a href="events.html">Events</a><a href="contact.html">Contact the ministry</a><a href="feedback.html">Feedback</a><a href="report-issue.html">Report a concern</a></div></div></div><div class="footer-middle">Ministry of Agriculture, Fisheries and Natural Resources · Square Country Government · <a href="sitemap.html" style="text-decoration:underline">All site pages</a></div></div><div class="footer-bottom"><div class="container"><span>© ${new Date().getFullYear()} Square Country Government · Demonstration portal</span><span><a href="accessibility.html">Accessibility</a> &nbsp; · &nbsp; <a href="privacy.html">Privacy</a> &nbsp; · &nbsp; <a href="cookies.html">Cookies</a> &nbsp; · &nbsp; <a href="terms.html">Terms</a> &nbsp; · &nbsp; <a href="sitemap.html">Site map</a></span></div></div></footer>`}
function home(){const quick=[['Register a holding','First step for new agricultural holdings','register-holding.html','sprout'],['Licences & permits','Browse all permit types','licences.html','clipboard'],['Farming','Advice for producers','agriculture.html','sprout'],['Fishing','Resources for fishers','fisheries.html','fish'],['Natural resources','Land, forests and water','natural-resources.html','trees']];return `<section class="hero"><img class="hero-image" src="images/pm-copy.png" onerror="this.onerror=null;this.src='assets/hero-fallback.svg'" alt="Rural landscape representing agriculture, fisheries and natural resources"><div class="hero-overlay"></div><div class="container" style="width:100%"><div class="hero-inner"><span class="hero-note">${icon('leaf')} SQUARE COUNTRY GOVERNMENT</span><h1>Growing prosperity.<br>Protecting our future.</h1><p>Supporting a productive agricultural sector, sustainable fisheries and responsible natural resource management across Square Country.</p><div class="button-row"><a href="services.html" class="btn btn-white">Explore our services ${icon('right')}</a><a href="news.html" class="btn btn-dark-outline">Latest news ${icon('right')}</a></div></div></div></section><section class="quicknav" aria-label="Popular services"><div class="container quicknav-grid">${quick.map(q=>`<a href="${q[2]}"><span class="quickicon">${icon(q[3])}</span><span><strong>${q[0]}</strong><small>${q[1]}</small></span></a>`).join('')}</div></section><section class="section"><div class="container"><div class="section-heading"><div><span class="kicker">Here to help</span><h2>Explore the ministry</h2><p>Find information, practical guidance and services across our three portfolios.</p></div>${link('about.html','About the ministry')}</div><div class="card-grid">${card('Agriculture','For farmers, growers and agricultural businesses.','agriculture.html','sprout')}${card('Fisheries','For commercial fishing, recreation and aquaculture.','fisheries.html','fish')}${card('Natural resources','For forests, water, public lands, minerals and conservation.','natural-resources.html','trees')}</div></div></section><section class="section soft"><div class="container"><div class="section-heading"><div><span class="kicker">Popular services</span><h2>What can we help you do?</h2><p>Quick routes to information and practical tools.</p></div>${link('services.html','View all services')}</div><div class="card-grid four">${card('Register an agricultural holding','Start here before applying for agricultural permissions.','register-holding.html','sprout',true)}${card('Apply for a licence','Find permit information and prepare a local draft.','licences.html','clipboard',true)}${card('Record a catch','Keep a personal catch log and export your records.','report-catch.html','file-text',true)}${card('View publications','Browse sector documents and printable resources.','publications.html','book',true)}${card('Report a concern','Prepare a message about an environmental or sector concern.','report-issue.html','shield',true)}</div></div></section><section class="section"><div class="container home-feature"><div><span class="kicker">Our commitment</span><h2>Supporting communities and caring for the places we share.</h2><p class="lead">From healthy farmland and productive fisheries to thriving forests and waterways, our work connects natural systems with economic opportunity.</p><ul class="check-list"><li>${icon('check-circle')} Clear information for businesses and the public</li><li>${icon('check-circle')} Responsible use of land and aquatic resources</li><li>${icon('check-circle')} Practical guidance and community participation</li><li>${icon('check-circle')} A focus on long-term resilience</li></ul><a href="strategies.html" class="btn btn-outline">Our strategic priorities ${icon('right')}</a></div><div class="feature-art"><img src="assets/hero-fallback.svg" alt="Illustration of land, fields and waterways"><span class="art-label">A sustainable future for Square Country</span></div></div></section><section class="section soft"><div class="container"><div class="section-heading"><div><span class="kicker">Ministry updates</span><h2>Latest news and announcements</h2><p>Read updates, guidance announcements and ministry information.</p></div>${link('news.html','All news')}</div><div class="news-grid">${D.news.slice(0,3).map((n,i)=>newsCard(n,i)).join('')}</div><div class="alert" style="font-size:12px;margin-top:23px"><strong>Demonstration news content</strong>These articles are examples written for the Square Country website, not verified statements of real ministry actions.</div></div></section><section class="section"><div class="container"><div class="mini-cta"><div><span class="eyebrow light">We’re here to help</span><h2>Need to find the right team?</h2><p>Search our guidance or prepare an enquiry for the ministry.</p></div><div class="button-row"><a class="btn btn-white" href="contact.html">Contact us ${icon('right')}</a><a class="btn btn-dark-outline" href="faq.html">FAQs</a></div></div></div></section>`}
function newsCard(n,i){return `<article class="news-card"><a class="news-visual ${i===1?'blue':i===2?'gold':''}" href="article.html?id=${encodeURIComponent(n.id)}" aria-label="Read: ${e(n.title)}">${icon(i===1?'sprout':i===2?'fish':'leaf')}</a><div class="news-body"><div class="item-meta"><span class="tag">${e(n.category)}</span><span>${formatDate(n.date)}</span></div><h3><a href="article.html?id=${encodeURIComponent(n.id)}">${e(n.title)}</a></h3><p>${e(n.lead)}</p>${link('article.html?id='+encodeURIComponent(n.id),'Read article')}</div></article>`}
function formatDate(iso){try{return new Date(iso+'T12:00:00').toLocaleDateString('en-NZ',{day:'numeric',month:'long',year:'numeric'})}catch{return iso}}
function asideFor(d,ids=[],extra=''){return `<aside class="aside"><div class="aside-block"><h3>In this section</h3>${(ids.length?ids:(D.nav.find(n=>n.label===d.group)?.items||[]).map(it=>it[1])).slice(0,8).map(id=>`<a href="${e(id)}">${e(displayTitle(id))}${icon('right')}</a>`).join('')}</div><div class="aside-block aside-highlight"><h3>Need help?</h3><p>Can’t find what you’re looking for? Prepare an enquiry or visit our frequently asked questions.</p><a href="contact.html">Contact the ministry ${icon('right')}</a></div>${extra}</aside>`}
function renderGuide(d,id){let cards=d.cards?.length?`<div class="landing-cards card-grid">${d.cards.map(c=>card(...c)).join('')}</div>`:'';let sections=(d.sections||[]).map((s,i)=>`<section class="content-section prose" id="section-${i}"><h2>${e(s.heading)}</h2>${s.text?`<p>${e(s.text)}</p>`:''}${s.bullets?`<ul>${s.bullets.map(b=>`<li>${e(b)}</li>`).join('')}</ul>`:''}</section>`).join('');let crumbsGroup=d.group;if(['Agriculture','Fisheries','Natural Resources'].includes(d.title))crumbsGroup='';return `${banner(d.title,d.description,crumbsGroup)}<div class="container page-layout"><main class="prose" id="content-area"><p class="lead" style="margin:0 0 34px">${e(d.intro)}</p>${cards}${sections}${id==='grants'?`<div class="info-panel gold"><strong>Programme status</strong><p>No confirmed open funding round is supplied in this website prototype. Do not rely on demonstration descriptions as an offer of funding.</p></div>`:''}<div class="info-panel blue"><strong>Information notice</strong><p>This guidance is an overview. For current statutory requirements, approvals and restrictions, use verified official sources or contact the responsible team.</p></div></main>${asideFor(d)}</div>${related(d.related)}`}
const permitFile=id=>({'agriculture':'agricultural-permit.html','commercial-fishing':'commercial-fishing-licence.html','recreational-fishing':'recreational-fishing-licence.html','aquaculture':'aquaculture-permit.html','forestry':'forestry-permit.html','water-use':'water-use-permit.html','mining':'mining-permit.html','land-access':'land-access-permit.html'}[id]);
function renderPermit(p){return `${banner(p.title,p.summary,'Services',`<a class="btn" href="application.html?service=${p.id}">Start a draft ${icon('right')}</a><a class="btn btn-outline" href="licences.html">All licences</a>`,'Licences and permits')}<div class="container page-layout"><main class="prose"><div class="service-meta"><span class="tag">${e(p.sector)}</span><span class="tag blue">${e(p.audience)}</span><span class="tag gold">Draft tool only</span></div><section class="content-section" style="margin-top:33px"><h2>About this service</h2><p>${e(p.summary)} This page describes common preparatory information rather than creating any entitlement to operate.</p></section><section class="content-section"><h2>Who this is for</h2><ul>${p.eligibility.map(x=>`<li>${e(x)}</li>`).join('')}</ul></section><section class="content-section"><h2>Information to prepare</h2><ul>${p.required.map(x=>`<li>${e(x)}</li>`).join('')}</ul></section><section class="content-section"><h2>How the process works</h2><ol class="step-list">${p.process.map(x=>`<li>${e(x)}</li>`).join('')}</ol></section><section class="content-section"><h2>Conditions and considerations</h2><p>${e(p.consideration)}</p><p>Specific fees, processing times, evidence standards, renewal arrangements and legal requirements have not been configured for this demonstration. Confirm these with the ministry before applying.</p></section><section class="content-section"><h2>Prepare an application draft</h2><p>Use our step-by-step browser tool to record key details, review them and download a copy. Drafts stay on this device and are <strong>not submitted</strong>.</p><div class="button-row"><a class="btn" href="application.html?service=${p.id}">Prepare draft ${icon('right')}</a><a class="btn btn-outline" href="my-applications.html">View saved drafts</a></div></section></main>${asideFor({group:p.sector},p.related,`<div class="aside-block"><h3>Service summary</h3><p class="small muted">Audience: ${e(p.audience)}</p><p class="small muted">Cost and processing time: to be officially confirmed</p></div>`)}</div>${related(p.related)}`}
function renderServices(){return `${banner('Services and information','Find guidance, services, records and tools across the ministry.','Services')}<section class="section"><div class="container"><div class="filterbar"><div class="field"><label for="service-search">Search services</label><input id="service-search" class="input" type="search" placeholder="Try: fishing, soil, permits, water"></div><div class="field selectfield"><label for="service-sector">Filter by sector</label><select id="service-sector" class="select"><option value="all">All sectors</option><option>Agriculture</option><option>Fisheries</option><option>Natural Resources</option><option>Services</option></select></div></div><p class="results-count" id="service-count" role="status"></p><div id="service-results"></div></div></section>`}
function allServices(){return [
 {title:'Register an agricultural holding',description:'First application to register an agricultural holding with MAFNR. Prepare holder, property and agricultural activity details.',sector:'Agriculture',url:'register-holding.html',icon:'sprout'},
...D.permits.map(p=>({title:p.title,description:p.summary,sector:p.sector,url:permitFile(p.id),icon:p.icon})),
...Object.entries(D.pages).filter(([id,p])=>['Agriculture','Fisheries','Natural Resources'].includes(p.group)).map(([id,p])=>({title:p.title,description:p.description,sector:p.group,url:id+'.html',icon:p.icon})),
{title:'Saved application drafts',description:'Review, export and delete draft applications kept in this browser.',sector:'Services',url:'my-applications.html',icon:'clipboard'},
{title:'Catch log tool',description:'Record fishing activity and export personal catch records.',sector:'Fisheries',url:'report-catch.html',icon:'file-text'},
{title:'Forms and downloads',description:'Download practical record templates and find printable publications.',sector:'Services',url:'downloads.html',icon:'download'},
{title:'Report a concern',description:'Prepare a report about an environmental or sector concern.',sector:'Services',url:'report-issue.html',icon:'alert'},
{title:'Contact the ministry',description:'Find contact guidance and prepare a message.',sector:'Services',url:'contact.html',icon:'mail'}];}
function renderHolding(){return `${banner('Register an agricultural holding','The first registration for a new agricultural holding with the ministry.','Services',`<a class="btn" href="#holding-form">Start registration draft ${icon('right')}</a>`,'Agricultural holding registration')}<section class="section"><div class="container" style="max-width:1030px"><div class="info-panel gold"><strong>Start here if you are registering a holding for the first time</strong>Registration establishes the basic details of an agricultural holding and its responsible holder. It is distinct from permission for specific agricultural activities, livestock movements, water use or other licences.</div><div class="card-grid">${card('1. Register your holding','Provide your contact details, the holding location, land tenure and intended agricultural use.','register-holding.html#holding-form','sprout',true)}${card('2. Ministry verification','The ministry checks information and may request documents or clarification.','contact.html','clipboard',true)}${card('3. MAFNR registration reference','Once approved through a real ministry process, registration details and any official reference are communicated securely.','faq.html','file-text',true)}</div><div class="page-layout" style="padding-top:45px;gap:35px"><main class="prose"><section class="content-section"><h2>Who must register?</h2><p>Anyone establishing a new agricultural holding should begin here, whether the holding is managed by an individual, a family, a partnership or an agricultural business. Existing registered holdings should contact the ministry before submitting a duplicate registration.</p></section><section class="content-section"><h2>Information you will need</h2><ul><li>Name and contact details for the person responsible for the holding</li><li>Holding name, physical location and postal address, if different</li><li>Land ownership, lease or management arrangements</li><li>Approximate holding area and current or intended farming activities</li><li>Optional existing property identifier and relevant additional notes</li></ul></section><section class="content-section"><h2>After registration</h2><p>You may need additional permissions for particular activities. <a href="agricultural-permit.html" class="text-link">Agricultural activity permits</a>, water-use permits and other authorisations are separate from this initial holding registration.</p></section></main>${asideFor({group:'Agriculture'},['agriculture.html','farming.html','agricultural-permit.html','contact.html'],`<div class="aside-block"><h3>Your MAFNR number</h3><p class="small muted">This demonstration cannot assign or look up an official MAFNR number. You will not receive one by saving a local draft.</p></div>`)}</div><div id="holding-form" class="form-panel holding-panel" style="scroll-margin-top:125px"><h2>Holding registration draft</h2><p class="form-intro">Complete the steps below to prepare your initial application. Save on this device or download a copy for the approved submission process.</p><div class="draft-banner">${icon('lock')} <span><strong>Private local draft only.</strong> This page does not submit a registration, verify land details or generate an official MAFNR number. Avoid entering national identity numbers or other sensitive identifiers.</span></div><div id="holding-wizard"></div></div></div></section>`}
function renderLicences(){return `${banner('Licences and permits','Find out which permissions may apply and prepare information for an application enquiry.','Services')}<section class="section"><div class="container"><div class="info-panel gold" style="margin-top:0"><strong>Important</strong>This is a planning directory, not a published legal licence register. Requirements, fees, dates and official application channels must be verified before relying on the information.</div><div class="filterbar"><div class="field"><label for="permit-search">Search permit types</label><input id="permit-search" class="input" type="search" placeholder="Search by permit or activity"></div><div class="field selectfield"><label for="permit-sector">Sector</label><select class="select" id="permit-sector"><option value="all">All sectors</option><option>Agriculture</option><option>Fisheries</option><option>Natural Resources</option></select></div></div><p id="permit-count" class="results-count" role="status"></p><div id="permit-results" class="card-grid"></div></div></section>`}
function renderNews(){return `${banner('News and updates','Read ministry information and examples of announcements across all our portfolios.','News & resources')}<section class="section"><div class="container"><div class="alert warn"><strong>Demonstration articles</strong>All articles shown here are illustrative website content. They are not real public notices or verified government announcements.</div><div class="filterbar"><div class="field"><label for="news-search">Search news</label><input class="input" type="search" id="news-search" placeholder="Search news titles or topics"></div><div class="field selectfield"><label for="news-category">Category</label><select id="news-category" class="select"><option value="all">All categories</option><option>Agriculture</option><option>Fisheries</option><option>Natural Resources</option><option>Ministry update</option></select></div></div><p id="news-count" class="results-count" role="status"></p><div id="news-results" class="news-grid"></div></div></section>`}
function renderArticle(){let n=D.news.find(n=>n.id===params.get('id'));if(!n)return renderNotFound();return `${banner(n.title,n.lead,'News & resources',`<a class="btn btn-outline" href="news.html">${icon('right')} All news</a>`,n.category)}<div class="container page-layout"><article class="prose"><div class="item-meta" style="margin-bottom:24px"><span class="tag">${e(n.category)}</span><span>${icon('calendar')} ${formatDate(n.date)}</span><span class="tag gold">Demonstration article</span></div><div class="article-cover">${icon(n.category==='Fisheries'?'fish':n.category==='Agriculture'?'sprout':n.category==='Natural Resources'?'trees':'leaf')}</div>${n.body.map(x=>`<p>${e(x)}</p>`).join('')}<div class="article-footer"><a class="btn btn-outline" href="news.html">Back to all news</a><button class="btn btn-ghost" type="button" data-print>${icon('printer')} Print article</button></div></article>${asideFor({group:'News & resources'},n.related)}</div>${related(n.related)}`}
function renderPublications(){return `${banner('Publications and documents','Browse printable resources, planning templates and general information documents.','News & resources')}<section class="section"><div class="container"><div class="filterbar"><div class="field"><label for="pub-search">Find a publication</label><input id="pub-search" class="input" type="search" placeholder="Search publication titles and topics"></div><div class="field selectfield"><label for="pub-category">Type</label><select id="pub-category" class="select"><option value="all">All types</option><option>Guidance</option><option>Strategy</option><option>Template</option><option>Services</option></select></div></div><p id="pub-count" class="results-count" role="status"></p><div id="pub-results"></div><p class="small muted">All resources are sample content and can be printed or saved as PDF from your browser.</p></div></section>`}
function renderPublication(){let p=D.publications.find(x=>x.id===params.get('doc'));if(!p)return renderNotFound();return `${banner(p.title,p.summary,'News & resources',`<button data-print type="button" class="btn">${icon('printer')} Print / Save as PDF</button>`,'Publication · '+p.category)}<div class="container page-layout"><article class="prose"><div class="item-meta"><span class="tag">${e(p.category)}</span><span>${e(p.year)}</span><span class="tag gold">Illustrative document</span></div><div class="info-panel" style="margin-top:24px"><strong>About this resource</strong><p>${e(p.summary)} It does not replace an approved policy, standard or legal requirement.</p></div>${p.sections.map(([h,t],i)=>`<section id="p-${i}" class="content-section"><h2>${i+1}. ${e(h)}</h2><p>${e(t)}</p></section>`).join('')}<div class="article-footer"><a class="btn btn-outline" href="publications.html">All publications</a><button class="btn btn-ghost" data-print>${icon('printer')} Print document</button></div></article>${asideFor({group:'News & resources'},['publications.html','downloads.html','contact.html'])}</div>`}
function renderConsultations(){return `${banner('Public consultations','Learn about current engagement opportunities and view the consultation archive.','News & resources')}<section class="section"><div class="container"><div class="alert warn"><strong>Sample consultations</strong>These entries demonstrate how consultations would be displayed. They are not official statutory public consultations.</div><div class="card-grid">${D.consultations.map(c=>`<article class="card card-fill"><span class="tag ${c.status.includes('completed')?'gray':'gold'}" style="align-self:start">${e(c.status)}</span><h3><a href="consultation.html?id=${e(c.id)}">${e(c.title)}</a></h3><p>${e(c.summary)}</p><p class="small muted">Sector: ${e(c.sector)}<br>Sample closing date: ${formatDate(c.closes)}</p>${link('consultation.html?id='+c.id,'Read consultation')}</article>`).join('')}</div></div></section>`}
function renderConsultation(){let c=D.consultations.find(c=>c.id===params.get('id'));if(!c)return renderNotFound();return `${banner(c.title,c.summary,'News & resources',`<a class="btn btn-outline" href="consultations.html">Browse consultations</a>`,'Consultation · '+c.sector)}<div class="container page-layout"><main class="prose"><div class="service-meta"><span class="tag ${c.status.includes('completed')?'gray':'gold'}">${e(c.status)}</span><span class="tag blue">Sample close: ${formatDate(c.closes)}</span></div><section class="content-section" style="margin-top:30px"><h2>Background</h2><p>${e(c.background)}</p></section><section class="content-section"><h2>Questions for consideration</h2><ol>${c.questions.map(q=>`<li>${e(q)}</li>`).join('')}</ol></section><section class="content-section"><h2>Prepare a response</h2><p>The response tool creates text locally that you can copy or email through your own software. It does not collect or submit official feedback.</p>${c.status.includes('completed')?`<div class="info-panel">This example consultation is shown as completed. Responses are not accepted through the demonstration.</div>`:`<div id="consult-response"></div>`}</section></main>${asideFor({group:'News & resources'},['consultations.html','feedback.html','contact.html'])}</div>`}
function renderNotices(){let notes=[['Biosecurity observation and reporting','Information reminder','2026-10-25','Please use appropriate precautions and seek expert advice when unusual pests or symptoms are observed.'],['Check regulations before undertaking a fishing activity','Fisheries reminder','2026-10-18','Confirm fishing licences, areas, seasons, gear and catch rules using current official information.'],['Public land activity planning','Land management','2026-10-06','Organised and commercial activity on public land may require permission before work begins.']];return `${banner('Public notices','Important information and public-facing reminders.','News & resources')}<section class="section"><div class="container"><div class="alert warn"><strong>Demonstration notice board</strong>No legally effective public notices or restrictions are published by this sample site. Replace notices with authorised text and dates before real-world use.</div>${notes.map(n=>`<article class="list-card"><div class="iconbox">${icon('alert')}</div><div><div class="item-meta"><span class="tag gold">${e(n[1])}</span><span>${formatDate(n[2])}</span></div><h3>${e(n[0])}</h3><p>${e(n[3])}</p></div></article>`).join('')}<div class="button-row" style="margin-top:27px"><a href="news.html" class="btn btn-outline">News archive</a><a href="contact.html" class="btn">Ask about a notice</a></div></div></section>`}
function renderEvents(){const events=[['2026-12-04','Agriculture information session','Agriculture','An example of a producer guidance and questions session.'],['2026-12-11','Fisheries operator workshop','Fisheries','Sample session exploring record-keeping and responsible fishing.'],['2027-01-19','Community land-care forum','Natural Resources','Illustrative public discussion about land and conservation topics.'],['2027-02-03','Public service design workshop','Ministry-wide','A proposed feedback workshop about improving ministry online services.']];return `${banner('Events and engagement','Upcoming sample workshops, community sessions and ministry engagement opportunities.','News & resources')}<section class="section"><div class="container"><div class="alert warn"><strong>Illustrative schedule</strong>These dates and events are examples only. They are not confirmed ministry events; no registrations are being accepted.</div><div class="filterbar"><div class="field selectfield"><label for="event-sector">Portfolio</label><select id="event-sector" class="select"><option value="all">All portfolios</option><option>Agriculture</option><option>Fisheries</option><option>Natural Resources</option><option>Ministry-wide</option></select></div></div><div id="events-list">${events.map(([date,title,sector,desc])=>`<article class="list-card event-item" data-sector="${e(sector)}"><span class="event-date"><strong>${date.slice(8)}</strong><span>${new Date(date+'T12:00:00').toLocaleDateString('en-NZ',{month:'short'})}</span></span><div><span class="tag">${e(sector)}</span><h3>${e(title)}</h3><p>${e(desc)}</p><span class="small muted">Sample date: ${formatDate(date)} · Venue and registration not confirmed</span></div></article>`).join('')}</div></div></section>`}
function renderFAQ(){return `${banner('Frequently asked questions','Find quick answers about services, licences and using this website.','Services')}<section class="section"><div class="container" style="max-width:940px"><div class="field"><label for="faq-search">Search questions</label><input id="faq-search" class="input" placeholder="Search FAQs" type="search"></div><p class="results-count" id="faq-count" role="status"></p><div id="faq-results">${D.faq.map(([q,a])=>`<details class="accordion"><summary>${e(q)} ${icon('chevron')}</summary><div class="accordion-content">${e(a)}</div></details>`).join('')}</div><div class="info-panel">Still have a question? <a href="contact.html" style="text-decoration:underline;font-weight:800">Contact the ministry</a> or explore the <a href="services.html" style="text-decoration:underline;font-weight:800">service directory</a>.</div></div></section>`}
function renderDownloads(){let files=[['Agricultural activity log','Keep a record of production activities and observations.','agriculture-record.csv'],['Personal fishing catch log','Record catches, species, location and gear.','catch-log-template.csv'],['Farm water-use log','Track water source, volume and purpose.','water-use-record.csv'],['Biosecurity observation checklist','List observations, signs and actions taken.','biosecurity-checklist.csv'],['Site visit inspection log','Document visits, hazards and follow-up actions.','site-inspection.csv']];return `${banner('Forms and downloads','Download practical templates and access printable guidance documents.','Services')}<section class="section"><div class="container"><div class="section-heading"><div><span class="kicker">Record templates</span><h2>Downloadable CSV templates</h2><p>Open these files in a spreadsheet programme or text editor. They are not official regulatory forms.</p></div></div>${files.map(f=>`<div class="download-row"><div class="iconbox">${icon('file-text')}</div><div class="file-info"><h3>${e(f[0])}</h3><p>${e(f[1])} · CSV file</p></div><a class="btn btn-outline" download href="downloads/${e(f[2])}">${icon('download')} Download</a></div>`).join('')}<div class="section-heading" style="margin-top:50px"><div><span class="kicker">Guides</span><h2>Printable documents</h2><p>Read, print, or use your browser’s Save as PDF option.</p></div></div><div class="card-grid">${D.publications.filter(x=>x.category==='Template'||x.category==='Guidance').slice(0,6).map(p=>card(p.title,p.summary,'publication.html?doc='+p.id,'book',true)).join('')}</div><div class="info-panel gold"><strong>Not official submission forms</strong>The licence draft wizard can export an editable JSON file. No downloadable file from this demonstration is proof of a regulatory submission.</div></div></section>`}
function renderSearch(){return `${banner('Search the website','Search guidance, services, licences, news, publications and consultations.','Services')}<section class="section"><div class="container"><form id="page-search-form" action="search.html" class="filterbar"><div class="field" style="flex:1"><label for="page-search">Search term</label><input class="input" id="page-search" type="search" name="q" value="${e(params.get('q')||'')}" placeholder="Search the ministry website"></div><button class="btn" type="submit" style="margin-bottom:17px">${icon('search')} Search</button></form><p class="results-count" id="search-count" role="status"></p><div id="search-results"></div></div></section>`}
function renderContact(kind){const defs={contact:{title:'Contact the ministry',desc:'Prepare a general enquiry or find the most relevant topic for your question.',lead:'Use this form to compose an email in your own email application. Nothing is submitted automatically.',submit:'Open email application',topics:['General enquiry','Agriculture','Fisheries','Natural Resources','Licences and permits','Publications','Other']},feedback:{title:'Website and service feedback',desc:'Tell us what could be clearer, more accessible or easier to use.',lead:'Compose constructive feedback to copy or open in your own email application.',submit:'Open email application',topics:['Website content','Accessibility','Service experience','Possible error','Other feedback']},'report-issue':{title:'Report a concern',desc:'Prepare a report about a biosecurity, environmental, fisheries or public land concern.',lead:'This form prepares a report for an official contact channel. It does not transmit an incident report.',submit:'Open email application',topics:['Suspected biosecurity risk','Fishing or marine concern','Public land damage','Water pollution or other environmental concern','Animal welfare concern','Other']}};let d=defs[kind];let caution=kind==='report-issue'?`<div class="info-panel gold"><strong>Urgent or dangerous situations</strong>Do not use this form for emergencies. Contact the appropriate emergency service or responsible authority using a verified contact channel. Avoid approaching potentially dangerous sites or handling suspicious material.</div>`:'';return `${banner(d.title,d.desc,kind==='contact'?'About':'Services')}<div class="container page-layout"><main><p class="lead">${e(d.lead)}</p>${caution}<div class="form-panel"><form id="message-form" data-kind="${e(kind)}"><div class="field-grid"><div class="field"><label for="msg-name">Your name <span class="required">*</span></label><input class="input" id="msg-name" name="name" required maxlength="120" autocomplete="name"></div><div class="field"><label for="msg-email">Email <span class="required">*</span></label><input class="input" type="email" id="msg-email" name="email" required maxlength="150" autocomplete="email"></div><div class="field full"><label for="msg-topic">Topic <span class="required">*</span></label><select class="select" id="msg-topic" name="topic" required><option value="">Select a topic</option>${d.topics.map(x=>`<option>${e(x)}</option>`).join('')}</select></div>${kind==='report-issue'?`<div class="field"><label for="msg-location">Location / area</label><input class="input" id="msg-location" name="location" placeholder="Where did this occur?"></div><div class="field"><label for="msg-date">Date observed</label><input type="date" class="input" id="msg-date" name="date"></div>`:''}<div class="field full"><label for="msg-subject">Subject <span class="required">*</span></label><input class="input" name="subject" id="msg-subject" required maxlength="160" placeholder="Short summary"></div><div class="field full"><label for="msg-body">${kind==='report-issue'?'What did you observe?':'Your message'} <span class="required">*</span></label><textarea class="textarea" id="msg-body" name="message" required rows="7" maxlength="5000" placeholder="Provide useful details and what help you need"></textarea><small>Please do not include passwords, banking details or other sensitive information.</small></div></div><div class="button-row" style="margin-top:13px"><button class="btn" type="submit">${icon('mail')} ${e(d.submit)}</button><button class="btn btn-outline" id="copy-message" type="button">${icon('clipboard')} Copy message</button><button class="btn btn-ghost" type="reset">Clear</button></div><p id="message-feedback" class="form-disclaimer" aria-live="polite" style="margin-top:16px">Configured demonstration address: ${e(D.contactEmail)}. Replace this with a verified contact address before publishing. Opening an email application does not guarantee delivery.</p></form></div></main><aside class="aside"><div class="aside-block"><h3>Enquiry channels</h3><p class="small muted">Contact email (example only)</p><p style="overflow-wrap:anywhere"><strong>${e(D.contactEmail)}</strong></p><hr class="divider"><p class="small muted">Postal address (to be confirmed)</p><p class="small">${e(D.address)}</p><p class="small muted">Phone: ${e(D.phone)}</p></div><div class="aside-block"><h3>Other useful links</h3><a href="faq.html">FAQs ${icon('right')}</a><a href="services.html">Services ${icon('right')}</a><a href="service-standards.html">Service standards ${icon('right')}</a><a href="accessibility.html">Accessibility help ${icon('right')}</a></div></aside></div>`}
function renderApplications(){return `${banner('Prepare an application draft','A guided tool to prepare and export an enquiry for one of the ministry permit types.','Services',`<a href="my-applications.html" class="btn btn-outline">${icon('clipboard')} Saved drafts</a>`,'Application preparation')}<section class="section" style="padding-top:49px"><div class="container" style="max-width:1020px"><div class="draft-banner">${icon('lock')} <span><strong>Your data stays in this browser.</strong> This tool does not send, receive, lodge or approve any official application. Export the draft and use a verified submission channel.</span></div><div id="application-tool" class="form-panel"></div></div></section>`}
function renderSavedApplications(){return `${banner('Saved draft applications','Review, continue, download or delete application drafts stored on this device.','Services')}<section class="section"><div class="container"><div class="info-panel blue"><strong>Local storage only</strong>Drafts are held in this browser on this device. They are not ministry records or submitted applications. Avoid storing confidential personal information on shared devices.</div><div class="section-heading"><div><h2>Your saved drafts</h2><p>Continue editing a draft or download a copy for your own records.</p></div><a class="btn" href="application.html">${icon('plus')} New draft</a></div><div id="saved-drafts"></div></div></section>`}
function renderCatchTool(){return `${banner('Personal catch log','Record catches, review entries and download a CSV copy of your data.','Services')}<section class="section" style="padding-top:52px"><div class="container"><div class="info-panel gold" style="margin-top:0"><strong>Personal log only — not official reporting</strong>Catch information remains in this browser and is not submitted to the ministry. Check whether a separate statutory report is required for your activity.</div><div class="card-grid catch-grid"><div class="form-panel"><h2>Add a catch entry</h2><p class="form-intro">Record one activity or species per entry.</p><form id="catch-form"><div class="field"><label for="catch-date">Date <span class="required">*</span></label><input id="catch-date" type="date" name="date" class="input" required></div><div class="field"><label for="catch-species">Species or catch description <span class="required">*</span></label><input id="catch-species" name="species" class="input" required maxlength="120" placeholder="Species / other catch"></div><div class="field-grid"><div class="field"><label for="catch-quantity">Quantity <span class="required">*</span></label><input id="catch-quantity" type="number" name="quantity" class="input" min="0" step="0.01" required></div><div class="field"><label for="catch-unit">Unit</label><select id="catch-unit" name="unit" class="select"><option>Number</option><option>kg</option></select></div></div><div class="field"><label for="catch-location">Fishing area</label><input id="catch-location" name="location" class="input" maxlength="120" placeholder="General area or site"></div><div class="field"><label for="catch-method">Gear or method</label><input id="catch-method" name="method" class="input" maxlength="120" placeholder="For example, line"></div><div class="field"><label for="catch-notes">Notes</label><textarea id="catch-notes" name="notes" class="textarea" rows="3" maxlength="600"></textarea></div><button class="btn" type="submit">${icon('plus')} Save entry locally</button></form></div><div><div class="section-heading"><div><h2>Saved entries</h2><p>Only visible on this device and browser.</p></div></div><div class="button-row" style="margin-bottom:18px"><button id="export-catch" class="btn btn-outline">${icon('download')} Export CSV</button><button id="clear-catch" class="btn btn-ghost">${icon('trash')} Delete all</button></div><div id="catch-entries"></div></div></div></div></section>`}
function renderStaticPage(id){const defs={
 careers:{title:'Careers and opportunities',desc:'Find information about working with the Ministry of Agriculture, Fisheries and Natural Resources.',group:'About',content:[['Working at the ministry','Our work connects public service, agriculture, fisheries, conservation, science and community engagement. Roles may include policy, operations, technical advice, administration and communications.'],['Current vacancies','No confirmed current vacancies are listed in this demonstration. Any official recruitment notice should include the role description, eligibility, selection process, closing date and verified application route.'],['Equal opportunity and accessibility','Recruitment information should be accessible and applicants should be able to request reasonable accommodations through approved channels.']],links:['about.html','contact.html','service-standards.html']},
 policies:{title:'Policies and guidance',desc:'Find ministry policy themes, good practice and supporting resources.',group:'News & resources',content:[['Policy areas','The ministry’s public policy work covers agricultural productivity, sustainable fisheries management, natural resource stewardship, biodiversity and accessible public services.'],['Official legal requirements','This website does not publish approved legal texts or binding standards. Any final policy should link to the authoritative act, regulation or official decision and clearly show its publication date.'],['Documents and public feedback','Find background publications in the resource library and any public engagement opportunities on the consultations page.']],links:['publications.html','consultations.html','strategies.html']},
 emergency:{title:'Urgent concerns and emergencies',desc:'Understand what to do when there is an immediate risk to people, animals or the environment.',group:'Services',content:[['Immediate danger','If there is an imminent threat to life, safety or property, use the appropriate emergency service through a verified local emergency number. This prototype does not provide a live emergency response service.'],['Environmental incident','Keep a safe distance, avoid handling suspicious materials and record the location and observations if it is safe to do so. Contact the responsible emergency or environmental authority.'],['Non-urgent issues','For non-urgent concerns you can prepare a report through the ministry concern form. Do not rely on the form for time-sensitive action.']],links:['report-issue.html','contact.html','biosecurity.html']},
 accessibility:{title:'Accessibility',desc:'How this website has been designed for broad, inclusive access.',group:'About',content:[['Using the website','The website supports keyboard navigation, visible focus indicators, semantic headings, form labels, high-contrast text and responsive layouts. You can use the “Skip to main content” link to bypass repetitive navigation.'],['Adjust the display','Use your browser controls to zoom text or the entire page. Layouts adapt to different screen sizes. Printing is supported on guides and documents.'],['Accessibility limitations','Certain features require JavaScript for navigation rendering and interactive tools. The image content and supplied ministry logo should be reviewed to ensure final text alternatives are accurate. No independent WCAG audit has been completed.'],['Reporting an issue','Use the feedback page to describe the page, browser and barrier encountered. An approved accessibility contact should be configured before public launch.']],links:['feedback.html','service-standards.html','contact.html']},
 privacy:{title:'Privacy statement',desc:'How this demonstration website handles information you enter.',group:'About',content:[['Information you provide','This static website does not operate a backend for application, contact, consultation or catch-reporting submissions. Interactive application and catch log records are stored locally using your browser’s localStorage where supported.'],['Who can see the information','The site does not transmit draft application or catch log content to ministry servers. Anyone with access to your browser profile or device may be able to view locally saved records. Avoid entering sensitive information on shared devices.'],['Email enquiries','When you select “Open email application”, your device may open a pre-filled message. You decide whether to send it. Delivery and handling depend on the actual recipient and your email provider.'],['Data retention and deletion','Drafts remain locally until you delete them or clear relevant browser data. You can remove application drafts and catch log entries within the website.'],['External tools and third parties','The site requests a Google Fonts stylesheet if available; system fonts are used otherwise. This sample does not install advertising trackers or an analytics system. The separate, user-supplied login page is outside this privacy description.'],['Official deployment','An approved privacy notice, data controller details, security review and legal retention requirements must be added if live digital submissions or analytics are introduced.']],links:['cookies.html','terms.html','my-applications.html']},
 cookies:{title:'Cookies and local storage',desc:'What browser storage is used by this demonstration website.',group:'About',content:[['Cookies','The demonstration code does not set first-party cookies. It does not provide analytics, advertising or tracking cookies. Separate third-party assets or a later login system may have their own practices.'],['Local browser storage','The application draft wizard and catch log use localStorage so that information remains available when you return on the same browser and device. LocalStorage is not a cookie and cannot synchronise between devices.'],['Your choices','Delete individual records using the tools provided, or clear this site’s data in your browser settings. Disabling storage may prevent saving drafts.'],['Before launch','Reassess this statement after adding analytics, authentication, server forms or other third-party services.']],links:['privacy.html','my-applications.html','report-catch.html']},
 terms:{title:'Terms and disclaimer',desc:'Important information about the use and limitations of this website.',group:'About',content:[['Demonstration and general guidance','This website is a demonstration for the fictional Square Country ministry. All guidance, sample news, public notices, consultation details, event dates and contact information are illustrative unless independently verified and formally approved.'],['Not a regulatory system','No permit or licence is issued through this website. Completing, saving, printing or downloading a form does not constitute an application, renewal, official notification or compliance record.'],['Accuracy and change','Legal conditions, fees, eligibility, seasons, quotas, deadlines and application procedures may change. Check official publications before relying on any information for practical decisions.'],['External services and login','The Login link points to login.html, an existing page intentionally not supplied in this package. External websites and future integrations may operate under separate terms.'],['Use of information','The site is offered on an illustrative basis. Review and confirm all material before treating it as official public guidance.']],links:['privacy.html','contact.html','accessibility.html']}}
;let x=defs[id];return `${banner(x.title,x.desc,x.group)}<div class="container page-layout"><main class="prose">${x.content.map(([h,t])=>`<section class="content-section"><h2>${e(h)}</h2><p>${e(t)}</p></section>`).join('')}</main>${asideFor({group:x.group},x.links)}</div>${related(x.links)}`}
function renderSiteMap(){let groups=D.nav.map(n=>[n.label,n.items]);groups.push(['Additional pages',[['Home','index.html'],['News articles','news.html'],['Register an agricultural holding','register-holding.html'],['Application draft wizard','application.html'],['Saved drafts','my-applications.html'],['Personal catch log','report-catch.html'],['Feedback','feedback.html'],['Report a concern','report-issue.html'],['Careers','careers.html'],['Policies','policies.html'],['Urgent concerns','emergency.html'],['Privacy','privacy.html'],['Cookies','cookies.html'],['Accessibility','accessibility.html'],['Terms and disclaimer','terms.html'],['Site map','sitemap.html']]]);groups.push(['Licence and permit information',D.permits.map(p=>[p.title,permitFile(p.id)])]);return `${banner('Site map','A directory of the website’s public pages and tools.','About')}<section class="section"><div class="container"><div class="card-grid">${groups.map(g=>`<section class="card"><h3 style="margin:0 0 15px">${e(g[0])}</h3><ul style="list-style:none;padding:0;margin:0">${g[1].map(([text,href])=>`<li style="margin:9px 0"><a href="${e(href)}" class="text-link" style="font-weight:650">${e(text)}</a></li>`).join('')}</ul></section>`).join('')}</div></div></section>`}
function renderNotFound(){document.title='Page not found | MAFNR';return `${banner('Page not found','The page or item you requested could not be found.','About')}<section class="section"><div class="container" style="max-width:790px;text-align:center"><div class="iconbox" style="margin:0 auto 22px">${icon('search')}</div><h2>Let’s help you find what you need.</h2><p class="lead">Check the address, search the website or browse the service directory.</p><div class="button-row" style="justify-content:center"><a href="index.html" class="btn">Return home</a><a href="search.html" class="btn btn-outline">Search pages</a><a href="sitemap.html" class="btn btn-outline">Site map</a></div></div></section>`}
function render(){const p=D.pages[page];let permitId=({'agricultural-permit':'agriculture','commercial-fishing-licence':'commercial-fishing','recreational-fishing-licence':'recreational-fishing','aquaculture-permit':'aquaculture','forestry-permit':'forestry','water-use-permit':'water-use','mining-permit':'mining','land-access-permit':'land-access'})[page];let P=permitId?D.permits.find(x=>x.id===permitId):null;let main=page==='index'?home():P?renderPermit(P):p?renderGuide(p,page):({services:renderServices,licences:renderLicences,news:renderNews,article:renderArticle,publications:renderPublications,publication:renderPublication,consultations:renderConsultations,consultation:renderConsultation,notices:renderNotices,events:renderEvents,faq:renderFAQ,downloads:renderDownloads,search:renderSearch,contact:()=>renderContact('contact'),feedback:()=>renderContact('feedback'),'report-issue':()=>renderContact('report-issue'),application:renderApplications,'register-holding':renderHolding,'my-applications':renderSavedApplications,'report-catch':renderCatchTool,sitemap:renderSiteMap,careers:()=>renderStaticPage('careers'),policies:()=>renderStaticPage('policies'),emergency:()=>renderStaticPage('emergency'),privacy:()=>renderStaticPage('privacy'),cookies:()=>renderStaticPage('cookies'),terms:()=>renderStaticPage('terms'),accessibility:()=>renderStaticPage('accessibility'),'404':renderNotFound}[page]||renderNotFound)();document.getElementById('app').innerHTML=header()+`<div id="main" tabindex="-1">${main}</div>`+footer();let h=document.querySelector('.page-banner h1')||document.querySelector('.hero h1');let title=h?.textContent||D.siteName;document.title=(page==='index'?D.siteName:title+' | '+D.shortName)+' | Square Country Government';let desc=document.querySelector('meta[name=description]');if(desc)desc.content=(document.querySelector('.page-banner .lead')||document.querySelector('.hero p'))?.textContent||D.disclaimer;}
function toast(message){let el=document.getElementById('toast');if(!el)return;el.textContent=message;el.classList.add('show');clearTimeout(window.__mafnrToast);window.__mafnrToast=setTimeout(()=>el.classList.remove('show'),4200)}
function handleGlobal(){document.querySelector('.mobile-menu-btn')?.addEventListener('click',ev=>{let b=ev.currentTarget;let open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));b.setAttribute('aria-label',open?'Close mobile menu':'Open mobile menu');b.innerHTML=icon(open?'x':'menu');document.querySelector('#mobile-nav').classList.toggle('open',open)});document.querySelectorAll('.nav-chevron').forEach(b=>b.addEventListener('click',ev=>{let group=ev.currentTarget.closest('.nav-group');let open=group.dataset.open!=='true';document.querySelectorAll('.nav-group[data-open]').forEach(g=>{g.dataset.open='false';g.querySelector('.nav-chevron').setAttribute('aria-expanded','false')});group.dataset.open=String(open);b.setAttribute('aria-expanded',String(open))}));document.addEventListener('click',ev=>{if(!ev.target.closest('.nav-group'))document.querySelectorAll('.nav-group[data-open]').forEach(g=>g.dataset.open='false')});const overlay=document.querySelector('.search-overlay');const close=()=>{overlay.classList.remove('open');overlay.setAttribute('aria-hidden','true');document.body.style.overflow='';document.querySelector('[data-open-search]')?.focus()};document.querySelectorAll('[data-open-search]').forEach(b=>b.addEventListener('click',()=>{overlay.classList.add('open');overlay.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';setTimeout(()=>overlay.querySelector('input')?.focus(),30)}));document.querySelector('[data-close-search]')?.addEventListener('click',close);overlay.addEventListener('click',ev=>{if(ev.target===overlay)close()});document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&overlay.classList.contains('open'))close()});document.querySelectorAll('[data-print]').forEach(b=>b.addEventListener('click',()=>window.print()))}
const filterText=(s,q)=>!q||String(s).toLowerCase().includes(q.toLowerCase());
function setupLists(){if(page==='services'){let all=allServices();let search=document.getElementById('service-search'),sector=document.getElementById('service-sector');let update=()=>{let items=all.filter(x=>(sector.value==='all'||x.sector===sector.value)&&filterText(x.title+' '+x.description+' '+x.sector,search.value));document.getElementById('service-count').textContent=`${items.length} service${items.length===1?'':'s'} found`;document.getElementById('service-results').innerHTML=items.length?items.map(x=>`<article class="list-card"><div class="iconbox">${icon(x.icon)}</div><div><span class="tag">${e(x.sector)}</span><h3><a href="${e(x.url)}">${e(x.title)}</a></h3><p>${e(x.description)}</p>${link(x.url,'View details')}</div><a class="arrow" href="${e(x.url)}" aria-label="View ${e(x.title)}">${icon('right')}</a></article>`).join(''):emptyState('No matching services','Try a different term or select all sectors.')};search.addEventListener('input',update);sector.addEventListener('change',update);update()}
if(page==='licences'){let search=document.getElementById('permit-search'),sector=document.getElementById('permit-sector');let update=()=>{let items=D.permits.filter(x=>(sector.value==='all'||x.sector===sector.value)&&filterText(x.title+' '+x.summary+' '+x.audience,search.value));document.getElementById('permit-count').textContent=`${items.length} permit type${items.length===1?'':'s'} found`;document.getElementById('permit-results').innerHTML=items.length?items.map(p=>`<article class="card card-fill"><span class="tag" style="align-self:start">${e(p.sector)}</span><div class="iconbox" style="margin-top:14px">${icon(p.icon)}</div><h3><a href="${permitFile(p.id)}">${e(p.title)}</a></h3><p>${e(p.summary)}</p>${link(permitFile(p.id),'Review requirements')}</article>`).join(''):emptyState('No matching permits','Try another search term.')};search.addEventListener('input',update);sector.addEventListener('change',update);update()}
if(page==='news'){let s=document.getElementById('news-search'),c=document.getElementById('news-category');let update=()=>{let items=D.news.filter(n=>(c.value==='all'||n.category===c.value)&&filterText(n.title+' '+n.lead+' '+n.body.join(' '),s.value));document.getElementById('news-count').textContent=`${items.length} article${items.length===1?'':'s'} found`;document.getElementById('news-results').innerHTML=items.length?items.map((n,i)=>newsCard(n,i)).join(''):emptyState('No matching articles','Try another term or clear the category filter.')};s.addEventListener('input',update);c.addEventListener('change',update);update()}
if(page==='publications'){let s=document.getElementById('pub-search'),c=document.getElementById('pub-category');let update=()=>{let items=D.publications.filter(x=>(c.value==='all'||x.category===c.value)&&filterText(x.title+' '+x.summary+' '+x.sections.flat().join(' '),s.value));document.getElementById('pub-count').textContent=`${items.length} publication${items.length===1?'':'s'} found`;document.getElementById('pub-results').innerHTML=items.length?items.map(x=>`<article class="list-card"><div class="iconbox">${icon('book')}</div><div><span class="tag">${e(x.category)}</span> <span class="small muted">${e(x.year)}</span><h3><a href="publication.html?doc=${e(x.id)}">${e(x.title)}</a></h3><p>${e(x.summary)}</p>${link('publication.html?doc='+x.id,'Read / print publication')}</div><a class="arrow" href="publication.html?doc=${e(x.id)}" aria-label="Open ${e(x.title)}">${icon('right')}</a></article>`).join(''):emptyState('No matching documents','Try searching for a broader topic.')};s.addEventListener('input',update);c.addEventListener('change',update);update()}
if(page==='faq'){let s=document.getElementById('faq-search');let update=()=>{let items=D.faq.filter(x=>filterText(x.join(' '),s.value));document.getElementById('faq-count').textContent=`${items.length} question${items.length===1?'':'s'} found`;document.getElementById('faq-results').innerHTML=items.length?items.map(([q,a])=>`<details class="accordion"><summary>${e(q)} ${icon('chevron')}</summary><div class="accordion-content">${e(a)}</div></details>`).join(''):emptyState('No matching questions','Try a shorter search term.')};s.addEventListener('input',update);update()}
if(page==='events'){let s=document.getElementById('event-sector');s.addEventListener('change',()=>{document.querySelectorAll('.event-item').forEach(x=>x.style.display=s.value==='all'||x.dataset.sector===s.value?'':'none')})}
if(page==='search'){let q=params.get('q')||'';let items=[...Object.entries(D.pages).map(([id,p])=>({title:p.title,summary:p.description+' '+p.intro,category:p.group,url:id+'.html',icon:p.icon})),...D.permits.map(p=>({title:p.title,summary:p.summary,category:'Licences',url:permitFile(p.id),icon:p.icon})),...D.news.map(n=>({title:n.title,summary:n.lead+' '+n.body.join(' '),category:'News',url:'article.html?id='+n.id,icon:'file-text'})),...D.publications.map(p=>({title:p.title,summary:p.summary+' '+p.sections.flat().join(' '),category:'Publications',url:'publication.html?doc='+p.id,icon:'book'})),...D.consultations.map(c=>({title:c.title,summary:c.summary,category:'Consultations',url:'consultation.html?id='+c.id,icon:'users'})),...['register-holding','services','licences','contact','faq','downloads','report-issue','report-catch','my-applications','notices','events','feedback','careers','policies','emergency','privacy','cookies','accessibility','terms','sitemap'].map(id=>({title:displayTitle(id+'.html'),summary:displayTitle(id+'.html')+' ministry service page',category:'Other pages',url:id+'.html',icon:'file-text'}))];let result=q.trim()?items.map(x=>({...x,rank:([x.title,x.summary,x.category].map((txt,i)=>filterText(txt,q)?(i===0?4:i===1?1:2):0)).reduce((a,b)=>a+b,0)})).filter(x=>x.rank>0).sort((a,b)=>b.rank-a.rank||a.title.localeCompare(b.title)):[];document.getElementById('search-count').textContent=q.trim()?`${result.length} result${result.length===1?'':'s'} for “${q.slice(0,120)}”`:'Enter a search term to search ministry pages.';document.getElementById('search-results').innerHTML=!q.trim()?`<div class="info-panel">Search by an activity, resource or topic, such as <a href="search.html?q=water" class="text-link">water</a> or <a href="search.html?q=fishing" class="text-link">fishing</a>.</div>`:result.length?result.map(x=>`<article class="list-card"><div class="iconbox">${icon(x.icon)}</div><div><span class="tag">${e(x.category)}</span><h3><a href="${e(x.url)}">${e(x.title)}</a></h3><p>${e(x.summary.slice(0,185))}${x.summary.length>185?'…':''}</p>${link(x.url,'Open result')}</div></article>`).join(''):emptyState('No results found','Try a different keyword or explore the site map.')}
}
function emptyState(title,desc){return `<div class="empty">${icon('search')}<h3>${e(title)}</h3><p>${e(desc)}</p></div>`}
function setupMessageForm(){let form=document.getElementById('message-form');if(!form)return;let kind=form.dataset.kind;let build=()=>{if(!form.reportValidity())return null;let data=Object.fromEntries(new FormData(form).entries());let body=`Name: ${data.name}\nReply email: ${data.email}\nTopic: ${data.topic}\n${data.location?'Location: '+data.location+'\n':''}${data.date?'Date observed: '+data.date+'\n':''}\n${data.message}\n\n[Prepared from MAFNR website prototype; not automatically sent]`;return {subject:`${kind==='report-issue'?'Concern':kind==='feedback'?'Feedback':'Enquiry'}: ${data.subject}`,body}};form.addEventListener('submit',ev=>{ev.preventDefault();let m=build();if(!m)return;let mail=`mailto:${encodeURIComponent(D.contactEmail)}?subject=${encodeURIComponent(m.subject)}&body=${encodeURIComponent(m.body)}`;document.getElementById('message-feedback').textContent='Opening your email application. Review the recipient and send the message yourself; no automatic submission has occurred.';location.href=mail});document.getElementById('copy-message')?.addEventListener('click',async()=>{let m=build();if(!m)return;let content=m.subject+'\n\n'+m.body;try{await navigator.clipboard.writeText(content);toast('Message copied to clipboard.')}catch{let ta=document.createElement('textarea');ta.value=content;document.body.append(ta);ta.select();document.execCommand('copy');ta.remove();toast('Message copied to clipboard.')}})}
function setupConsultation(){if(page!=='consultation')return;let c=D.consultations.find(x=>x.id===params.get('id'));let mount=document.getElementById('consult-response');if(!c||!mount)return;mount.innerHTML=`<form id="consult-form" class="form-panel"><div class="field"><label for="consult-name">Name (optional)</label><input id="consult-name" class="input" maxlength="100"></div>${c.questions.map((q,i)=>`<div class="field"><label for="answer-${i}">${e(q)}</label><textarea class="textarea" rows="3" id="answer-${i}" maxlength="1500"></textarea></div>`).join('')}<div class="button-row"><button type="button" id="consult-copy" class="btn">${icon('clipboard')} Copy response</button><button type="button" id="consult-email" class="btn btn-outline">${icon('mail')} Open email app</button></div><p class="form-disclaimer" style="margin-top:12px">These controls only prepare a message. This is not an official consultation submission.</p></form>`;let response=()=>`${c.title}\nParticipant: ${document.getElementById('consult-name').value||'Not provided'}\n\n${c.questions.map((q,i)=>q+'\n'+(document.getElementById('answer-'+i).value||'(No response)')).join('\n\n')}`;document.getElementById('consult-copy').addEventListener('click',async()=>{let text=response();try{await navigator.clipboard.writeText(text);toast('Consultation response copied.')}catch{let t=document.createElement('textarea');t.value=text;document.body.append(t);t.select();document.execCommand('copy');t.remove();toast('Response copied.')}});document.getElementById('consult-email').addEventListener('click',()=>{location.href=`mailto:${encodeURIComponent(D.contactEmail)}?subject=${encodeURIComponent('Sample consultation response: '+c.title)}&body=${encodeURIComponent(response())}`})}
const KEY_DRAFTS='mafnr-demo-application-drafts-v1',KEY_CATCH='mafnr-demo-catch-log-v1';
function stored(key){try{let a=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(a)?a:[]}catch{return []}}
function setStored(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('Browser storage is unavailable. Download your data instead.');return false}}
function createDownload(text,file,type='application/json'){let blob=new Blob([text],{type:type+';charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=file;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function stamp(){return new Date().toISOString()}
function newID(){return 'draft-'+Date.now()+'-'+Math.random().toString(36).slice(2,7)}
function setupApplication(){let mount=document.getElementById('application-tool');if(!mount)return;let id=params.get('draft');let draft=stored(KEY_DRAFTS).find(x=>x.id===id)||{id:newID(),service:D.permits.some(x=>x.id===params.get('service'))?params.get('service'):'agriculture',createdAt:stamp(),updatedAt:stamp(),fields:{}};let step=0,steps=['Applicant','Activity','Supporting details','Review & export'];let fields=draft.fields||{};
const val=k=>e(fields[k]??'');const permit=()=>D.permits.find(x=>x.id===draft.service)||D.permits[0];
const inp=(name,label,opt={})=>`<div class="field ${opt.full?'full':''}"><label for="f-${name}">${e(label)} ${opt.req?'<span class="required">*</span>':''}</label>${opt.tag==='textarea'?`<textarea id="f-${name}" class="textarea" rows="${opt.rows||4}" name="${name}" ${opt.req?'required':''} maxlength="${opt.max||1500}" placeholder="${e(opt.placeholder||'')}">${val(name)}</textarea>`:`<input class="input" id="f-${name}" name="${name}" type="${opt.type||'text'}" ${opt.req?'required':''} ${opt.type==='email'?'autocomplete="email"':''} maxlength="${opt.max||200}" placeholder="${e(opt.placeholder||'')}" value="${val(name)}">`}${opt.help?`<small>${e(opt.help)}</small>`:''}</div>`;
function save(){draft.updatedAt=stamp();draft.fields=fields;let all=stored(KEY_DRAFTS);let index=all.findIndex(x=>x.id===draft.id);if(index===-1)all.unshift(draft);else all[index]=draft;return setStored(KEY_DRAFTS,all)}
function collect(validate){let form=mount.querySelector('#wizard-form');if(!form)return true;if(validate&&!form.reportValidity())return false;let data=new FormData(form);if(step===0){draft.service=data.get('service')||draft.service;['name','email','organisation','phone'].forEach(k=>fields[k]=data.get(k)||'')}if(step===1){['activity','location','startDate','endDate','description'].forEach(k=>fields[k]=data.get(k)||'')}if(step===2){['siteRights','documents','impacts','notes'].forEach(k=>fields[k]=data.get(k)||'');fields.confirm=!!data.get('confirm')}return true}
function renderWizard(message=''){let p=permit();let body='';if(step===0)body=`<div class="form-section"><h2>1. Applicant information</h2><p class="form-intro">Select the service and provide contact details for your draft.</p><form id="wizard-form"><div class="field"><label for="f-service">Service / permit type <span class="required">*</span></label><select class="select" id="f-service" name="service">${D.permits.map(x=>`<option value="${e(x.id)}" ${draft.service===x.id?'selected':''}>${e(x.title)}</option>`).join('')}</select></div><div class="field-grid">${inp('name','Applicant name',{req:true})}${inp('email','Contact email',{req:true,type:'email'})}${inp('organisation','Business / organisation (if any)')}${inp('phone','Phone number')}</div></form></div>`;
if(step===1)body=`<div class="form-section"><h2>2. Proposed activity</h2><p class="form-intro">Describe what you intend to do. Check the service guidance for specific documentation that may be needed.</p><form id="wizard-form"><div class="field-grid">${inp('activity','Activity / project title',{req:true,full:true,placeholder:'Short name for your proposal'})}${inp('location','Site, property or area',{req:true,full:true,placeholder:'Location, parcel or general area'})}${inp('startDate','Proposed start date',{type:'date'})}${inp('endDate','Proposed end date',{type:'date'})}${inp('description','Activity description',{tag:'textarea',req:true,full:true,rows:6,max:3000,placeholder:'What is being proposed, and how will it be carried out?'})}</div></form></div>`;
if(step===2)body=`<div class="form-section"><h2>3. Supporting details</h2><p class="form-intro">Help the ministry understand the proposal. No documents can be uploaded to a government system from this prototype.</p><form id="wizard-form">${inp('siteRights','Site ownership / access arrangements',{tag:'textarea',rows:3})}${inp('documents','Supporting documents available',{tag:'textarea',rows:3,placeholder:'Describe plans, maps, assessments, or other files you hold'})}${inp('impacts','Environmental, safety or biosecurity considerations',{tag:'textarea',rows:4})}${inp('notes','Other relevant details',{tag:'textarea',rows:3})}<label class="check-row"><input type="checkbox" name="confirm" required ${fields.confirm?'checked':''}><span>I understand this is only a local draft and is not a legally submitted permit application. <span class="required">*</span></span></label></form></div>`;
if(step===3)body=`<div class="form-section"><h2>4. Review and export</h2><p class="form-intro">Review the information below. You can go back and make changes, print this summary or download a structured JSON file.</p><div class="info-panel gold"><strong>Not submitted</strong>This draft exists only in your browser and cannot produce an official permit, licence, approval, receipt or application number.</div><h3>Service</h3><p>${e(p.title)}</p><dl class="summary-dl">${[['Applicant','name'],['Email','email'],['Organisation','organisation'],['Phone','phone'],['Activity title','activity'],['Location','location'],['Start date','startDate'],['End date','endDate'],['Activity description','description'],['Site rights','siteRights'],['Supporting documentation','documents'],['Impacts and controls','impacts'],['Other notes','notes']].map(([label,key])=>`<dt>${label}</dt><dd>${e(fields[key]||'—').replaceAll('\n','<br>')}</dd>`).join('')}</dl><div class="button-row" style="margin-top:25px"><button type="button" id="export-draft" class="btn">${icon('download')} Download JSON draft</button><button type="button" data-print class="btn btn-outline">${icon('printer')} Print summary</button><a href="my-applications.html" class="btn btn-ghost">Saved drafts ${icon('right')}</a></div><p class="form-disclaimer" style="margin-top:19px">To apply officially, check the relevant ministry service instructions and use an approved channel.</p></div>`;
mount.innerHTML=`<div class="form-progress" aria-label="Draft steps">${steps.map((s,i)=>`<div class="step ${step===i?'active':step>i?'done':''}"><b>${step>i?icon('check'):i+1}</b>${e(s)}</div>`).join('')}</div>${message?`<div class="form-feedback" role="status">${e(message)}</div>`:''}${body}<div class="form-actions no-print"><button type="button" class="btn btn-outline" id="wizard-back" ${step===0?'disabled':''}>Back</button><div class="right"><button type="button" id="wizard-save" class="btn btn-ghost">${icon('check')} Save draft</button>${step<3?`<button type="button" id="wizard-next" class="btn">Continue ${icon('right')}</button>`:'<a class="btn btn-outline" href="licences.html">Explore permits</a>'}</div></div>`;
mount.querySelector('#wizard-next')?.addEventListener('click',()=>{if(!collect(true))return;save();step++;renderWizard();window.scrollTo({top:230,behavior:'smooth'})});mount.querySelector('#wizard-back')?.addEventListener('click',()=>{collect(false);save();step=Math.max(0,step-1);renderWizard()});mount.querySelector('#wizard-save')?.addEventListener('click',()=>{collect(false);save();renderWizard('Draft saved locally. It has not been submitted.')});mount.querySelector('#export-draft')?.addEventListener('click',()=>{save();createDownload(JSON.stringify({...draft,notice:'UNSUBMITTED LOCAL DRAFT — THIS IS NOT AN OFFICIAL APPLICATION'},null,2),`MAFNR-${draft.service}-${draft.id}.json`);toast('JSON draft downloaded. No application was submitted.')});mount.querySelectorAll('[data-print]').forEach(b=>b.addEventListener('click',()=>window.print()));}
renderWizard(id?'Existing draft loaded from this browser.':'You can save at any step and continue later from Saved drafts.')}
function setupSaved(){let node=document.getElementById('saved-drafts');if(!node)return;function draw(){let drafts=stored(KEY_DRAFTS).sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)));node.innerHTML=drafts.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Service and applicant</th><th>Updated</th><th>Status</th><th>Actions</th></tr></thead><tbody>${drafts.map(x=>{let p=D.permits.find(p=>p.id===x.service),name=x.fields?.name||'Unnamed draft';return `<tr><td><strong>${e(p?.title||x.service)}</strong><br><span class="small muted">${e(name)}</span></td><td>${e(new Date(x.updatedAt).toLocaleDateString('en-NZ'))}</td><td><span class="tag gold">Not submitted</span></td><td><div class="inline-actions"><a class="btn btn-outline" href="application.html?draft=${encodeURIComponent(x.id)}">${icon('edit')} Edit</a><button type="button" class="btn btn-ghost" data-download-draft="${e(x.id)}" aria-label="Download draft">${icon('download')}</button><button type="button" class="btn btn-ghost" data-delete-draft="${e(x.id)}" aria-label="Delete draft">${icon('trash')}</button></div></td></tr>`}).join('')}</tbody></table></div>`:emptyState('No saved drafts','Start a new application draft to see it here.');node.querySelectorAll('[data-download-draft]').forEach(b=>b.addEventListener('click',()=>{let x=stored(KEY_DRAFTS).find(x=>x.id===b.dataset.downloadDraft);if(x)createDownload(JSON.stringify({...x,notice:'UNSUBMITTED LOCAL DRAFT'},null,2),'MAFNR-'+x.id+'.json')}));node.querySelectorAll('[data-delete-draft]').forEach(b=>b.addEventListener('click',()=>{let key=b.dataset.deleteDraft;if(confirm('Delete this local draft permanently from this browser?')){setStored(KEY_DRAFTS,stored(KEY_DRAFTS).filter(x=>x.id!==key));draw();toast('Draft deleted from this browser.')}}))}draw()}
function csvCell(value){let s=String(value??'');return '"'+s.replaceAll('"','""')+'"'}
function setupCatch(){let form=document.getElementById('catch-form');if(!form)return;let date=form.querySelector('[name=date]');date.value=new Date().toLocaleDateString('en-CA');function draw(){let rows=stored(KEY_CATCH);document.getElementById('catch-entries').innerHTML=rows.length?`<p class="results-count">${rows.length} locally saved entr${rows.length===1?'y':'ies'}</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Species</th><th>Quantity</th><th>Area</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${e(x.date)}</td><td><strong>${e(x.species)}</strong><br><span class="small muted">${e(x.method||'')}</span></td><td>${e(x.quantity)} ${e(x.unit)}</td><td>${e(x.location||'—')}</td><td><button class="btn btn-ghost" type="button" data-delete-catch="${e(x.id)}" aria-label="Delete catch record">${icon('trash')}</button></td></tr>`).join('')}</tbody></table></div>`:emptyState('No catch entries yet','Add a record to build a personal catch log.');document.querySelectorAll('[data-delete-catch]').forEach(b=>b.addEventListener('click',()=>{if(confirm('Delete this catch entry from this browser?')){setStored(KEY_CATCH,stored(KEY_CATCH).filter(x=>x.id!==b.dataset.deleteCatch));draw();toast('Catch entry deleted.')}}))}form.addEventListener('submit',ev=>{ev.preventDefault();if(!form.reportValidity())return;let data=Object.fromEntries(new FormData(form).entries());setStored(KEY_CATCH,[{...data,id:newID(),createdAt:stamp()},...stored(KEY_CATCH)]);form.reset();date.value=new Date().toLocaleDateString('en-CA');draw();toast('Catch entry saved locally; no official report sent.')});document.getElementById('export-catch').addEventListener('click',()=>{let rows=stored(KEY_CATCH);if(!rows.length){toast('Add a catch record before exporting.');return}let cols=['date','species','quantity','unit','location','method','notes'];let csv=[cols.join(','),...rows.map(x=>cols.map(k=>csvCell(x[k])).join(','))].join('\r\n');createDownload('\ufeff'+csv,'MAFNR-personal-catch-log.csv','text/csv');toast('Catch log CSV downloaded.')});document.getElementById('clear-catch').addEventListener('click',()=>{if(!stored(KEY_CATCH).length)return;if(confirm('Delete all local catch records on this device? This cannot be undone.')){setStored(KEY_CATCH,[]);draw();toast('All catch entries deleted.')}});draw()}
render();handleGlobal();setupLists();setupMessageForm();setupConsultation();setupApplication();setupSaved();setupCatch();
})();
